function norm(s){
const start=parseInt(s.start,16),end=parseInt(s.end_exclusive,16);
return ins(s).map(i=>{
let a=i.args;const rip=a.match(/#\s*([0-9a-f]+)/);a=a.replace(/\s*#.*$/,"").replace(/\s*<.*$/,"");
if(rip&&/%rip/.test(a))a=a.replace(/-?0x[0-9a-f]+\(%rip\)/,`RIP_TARGET_${rip[1]}`);
if(/^(?:j\w+|call\w*)$/.test(i.op))a=a.replace(/^([0-9a-f]+)/,h=>{const n=parseInt(h,16);return n>=start&&n<end?"SELF+"+(n-start).toString(16):"ABS_"+h;});
return `${i.op} ${a}`.trim();
});}
